//! Actual Node24.13 FSReqAfterScope for the selected FSReqPromise requests.
//! The physical request supplies its real, idempotent native cleanup operation.
//! This scope owns a BaseObjectPtr and a genuine local HandleScope; it does not
//! allocate another Promise, retain another wrapper JS root, or change waiting.
const a = @import("native_node_argument_values.zig");
const requests = @import("native_node_fs_request_promise.zig");
const errors = @import("native_node_uv_exception.zig");
const c = a.c;
const Scope = a.Scope;

/// Private compiled-I/O operation corresponding to uv_fs_req_cleanup. The
/// stable raw owner and all syscall/path bytes remain live until it is called.
/// Its implementation is native only; no arbitrary guest callback is accepted.
pub const Cleanup = struct {
    raw: *anyopaque,
    run: *const fn (*anyopaque) void,
};

pub const AfterScope = struct {
    handles: Scope,
    request: ?*requests.Request = null,
    cleanup: Cleanup,
    initialized: bool = false,
    finished: bool = false,

    /// Caller storage is stable through finish. The original native strong
    /// pointer is initialized before HandleScope/Context::Scope construction.
    pub fn init(self: *AfterScope, request: *requests.Request, cleanup: Cleanup) !void {
        const engine = try request.environment().requireEngine();
        try request.wrap.retainNative();
        self.* = .{
            .handles = Scope.init(engine), .request = request,
            .cleanup = cleanup, .initialized = true,
        };
    }

    /// Destructor-body ordering: cleanup the real physical request, detach the
    /// native BaseObject, then reset this scope's native pointer. The original
    /// enclosing HandleScope still owns its Local values throughout this call.
    pub fn clear(self: *AfterScope) !void {
        const request = self.request orelse return;
        self.cleanup.run(self.cleanup.raw);
        try request.wrap.detach();
        self.request = null;
        // This may delete the native request when Dispatch failed and no
        // MakeLibuvRequestCallback pointer surrounds the original callback.
        try request.wrap.releaseNative();
    }

    /// This is the real Proceed predicate. An environment already stopping
    /// skips JS settlement; finish still performs the original native cleanup.
    pub fn proceed(self: *AfterScope, input: errors.Input) !bool {
        const request = self.request orelse return error.ActualFSAfterScopeRequestRequired;
        if (!request.environment().canCallIntoJs()) return false;
        if (input.code < 0) {
            try self.reject(input);
            return false;
        }
        return true;
    }

    /// Reject's local BaseObjectPtr survives Clear, then the actual request's
    /// Reject performs its own callback scope and live "promise" property Get.
    fn reject(self: *AfterScope, input: errors.Input) !void {
        const request = self.request orelse return error.ActualFSAfterScopeRequestRequired;
        try request.wrap.retainNative();
        var failure: ?anyerror = null;
        self.rejectBody(request, input) catch |err| {
            self.handles.boundary.escaping();
            failure = err;
        };
        request.wrap.releaseNative() catch |err| {
            self.handles.boundary.escaping();
            if (failure == null) failure = err;
        };
        if (failure) |err| return err;
    }
    fn rejectBody(self: *AfterScope, request: *requests.Request, input: errors.Input) !void {
        // UVException is created while the native request's original strings
        // still exist. Clear then runs before any live request promise lookup.
        const reason = try self.handles.own(try errors.create(self.handles.engine, input));
        try self.clear();
        try request.reject(reason);
    }

    /// A caller invokes finish on every initialized path, including ordinary
    /// callback failure and stopped-runtime completion. Preserve that failure
    /// before native pointer destruction can produce another pending reason.
    pub fn finish(self: *AfterScope, incoming: anyerror!void) !void {
        if (!self.initialized or self.finished) return incoming;
        self.finished = true;
        var failure: ?anyerror = null;
        if (incoming) |_| {} else |err| {
            self.handles.boundary.escaping();
            if (err == error.OutOfMemory and !self.handles.boundary.fatal) {
                _ = self.handles.engine.throwNativeOutOfMemoryFatal();
                self.handles.boundary.escaping();
            }
            failure = err;
        }
        self.clear() catch |err| {
            self.handles.boundary.escaping();
            if (failure == null) failure = err;
        };
        const result = try self.handles.finish(if (failure) |err|
            @as(anyerror!c.JSValue, err) else c.pi_js_undefined());
        self.handles.engine.freeValue(result);
    }
};

//! Actual ReqWrap dispatch and AfterInteger completion for the private read
//! binding. The existing Environment owns the only request queue/counter; the
//! shared Hub service owns the only libuv thread, event FIFO and stop/join.
const std = @import("std");
const a = @import("native_node_argument_values.zig");
const callbacks = @import("native_node_callback_scope.zig");
const request_state = @import("native_node_request_state.zig");
const requests = @import("native_node_fs_request_promise.zig");
const after_scope = @import("native_node_fs_after_scope.zig");
const shared_service = @import("native_node_uv_service.zig");
const env_io = @import("native_env_io.zig");
const Completion = @import("native_sdk_owned_completion.zig").Completion;
const c = a.c;
pub const uv = shared_service.uv;
pub const Engine = a.v.em.Engine;
const Scope = a.Scope;
const controller_tag: u8 = 0;
pub const Acquisition = union(enum) { ready: *Controller, failed: c_int };

pub const Controller = struct {
    hub: *env_io.Hub,
    environment: *callbacks.Environment,
    service: *uv.PiUvService,
    busy: usize = 0,
    stopping: bool = false,
    references: usize = 1, // Hub plus actual retained native binding owners.

    pub fn retain(self: *Controller) *Controller {
        std.debug.assert(self.references != 0);
        self.references += 1;
        return self;
    }
    pub fn release(self: *Controller) void {
        std.debug.assert(self.references != 0);
        self.references -= 1;
        if (self.references != 0) return;
        std.debug.assert(self.stopping);
        const environment = self.environment;
        uv.pi_uv_service_release(self.service);
        environment.allocator().destroy(self);
        environment.release();
    }
    pub fn beginCall(self: *Controller, engine: *Engine) !void { return self.enter(engine); }
    pub fn endCall(self: *Controller) void { self.leave(); }

    fn enter(self: *Controller, engine: *Engine) !void {
        // A retained actual binding can outlive the Hub. Never dereference
        // that retired Hub after its native resource has been stopped.
        if (self.stopping) return error.NativeEnvClosed;
        try self.hub.assertOwner();
        if ((try self.environment.requireEngine()) != engine or self.hub.engine != engine)
            return error.ActualFSRequestEnvironmentMismatch;
        if (self.stopping or self.hub.stopping) return error.NativeEnvClosed;
        self.busy += 1;
    }
    fn leave(self: *Controller) void {
        std.debug.assert(self.busy != 0);
        self.busy -= 1;
    }

    /// Creation uses the caller's real HandleScope and native constructor
    /// allocation cutpoint. No extra Promise or native request is made at
    /// Dispatch. The caller preserves this Local through SetReturnValue.
    pub fn createReadRequest(self: *Controller, s: *Scope, factory: c.JSValue) !*requests.Request {
        try self.enter(s.engine);
        defer self.leave();
        const wrapper = try s.own(try requests.createPhysicalRequest(s, factory,
            false, cancelRequest, .{ .service = self.service, .kind = uv.PI_UV_FS_READ }));
        const request = try requests.unwrap(s.engine, factory, wrapper);
        if (request.environment() != self.environment)
            return error.ActualFSRequestEnvironmentMismatch;
        return request;
    }

    /// Private inputs were checked by the genuine native Read binding. The
    /// stored request is the one constructed above, not a worker Task copy.
    /// An immediate negative Dispatch calls the original AfterInteger directly
    /// and never enters Wrapper or the waiting counter.
    pub fn dispatchRead(self: *Controller, s: *Scope, request: *requests.Request,
        descriptor: c_int, backing: *const c.JSPiArrayBufferLease,
        offset: usize, length: u32, position: i64) !void
    {
        try self.enter(s.engine);
        defer self.leave();
        if (request.environment() != self.environment or
            request.entry.cancel_native != cancelRequest or request.entry.dispatched or
            backing.owner == null or length > std.math.maxInt(i32) or
            offset > backing.byte_length or length > backing.byte_length - offset)
            return error.ActualFSReadDispatchInputsRequired;
        const actual = request.native_request orelse return error.ActualFSNativeRequestRequired;
        request.entry.dispatchStarted();
        const status = uv.pi_uv_fs_read(actual, descriptor, @ptrCast(backing),
            offset, length, position);
        if (status >= 0) {
            try request.entry.dispatchAccepted();
            return;
        }
        // AfterInteger may delete the native request. Do not read it afterward.
        try afterInteger(request, actual);
    }

    fn ready(raw: *anyopaque) bool {
        const self: *Controller = @ptrCast(@alignCast(raw));
        return self.busy == 0;
    }
    fn find(self: *Controller, actual: *uv.PiUvFsRequest) !*requests.Request {
        // The genuine intrusive Environment queue is authoritative. The
        // compiled cancellation function identifies this derived owner before
        // taking the containing Request; no parallel registry owns JS roots.
        var cursor = self.environment.requests.head;
        while (cursor) |entry| : (cursor = entry.next) {
            if (entry.cancel_native != cancelRequest) continue;
            const request: *requests.Request = @alignCast(@fieldParentPtr("entry", entry));
            if (request.native_request == actual) return request;
        }
        return error.ActualFSCompletionRequestRequired;
    }
    fn deliver(raw: *anyopaque, event: *uv.PiUvEvent) !void {
        const self: *Controller = @ptrCast(@alignCast(raw));
        try self.hub.assertOwner();
        const actual = uv.pi_uv_event_fs_request(event) orelse
            return error.ActualFSCompletionEventRequired;
        const request = try self.find(actual);
        if (!request.entry.dispatched or !request.entry.counted)
            return error.ActualFSAcceptedCompletionRequired;
        self.busy += 1;
        defer self.leave();
        // MakeLibuvRequestCallback::Wrapper: native strong pointer, Detach,
        // decrement, then the original callback. Its pointer retires last.
        try request.entry.beginCallback();
        const engine = self.hub.engine;
        var handles = Scope.init(engine);
        var failure: ?anyerror = null;
        afterInteger(request, actual) catch |err| {
            record(&handles, err);
            failure = err;
        };
        request.entry.endCallback() catch |err| {
            record(&handles, err);
            if (failure == null) failure = err;
        };
        const ignored = try handles.finish(if (failure) |err|
            @as(anyerror!c.JSValue, err) else c.pi_js_undefined());
        engine.freeValue(ignored);
    }
    fn abandon(raw: *anyopaque, event: *uv.PiUvEvent) !void {
        const self: *Controller = @ptrCast(@alignCast(raw));
        // Original AfterScope::Proceed reads this actual Environment state.
        // Lifecycle must disable JS before Hub shutdown; no fake completion
        // or forced Promise settlement substitutes for that transition.
        if (self.environment.canCallIntoJs())
            return error.ActualFSShutdownJavascriptDisableRequired;
        return deliver(raw, event);
    }
    fn stop(raw: *anyopaque) void {
        const self: *Controller = @ptrCast(@alignCast(raw));
        if (self.stopping) return;
        std.debug.assert(self.busy == 0);
        if (self.environment.canCallIntoJs())
            @panic("actual Node environment must disable JS before FS shutdown");
        self.stopping = true;
        // The sole shared service resource was registered first. It has joined
        // all native callbacks, while its event FIFO still owns their results.
        const state = uv.pi_uv_service_snapshot(self.service);
        if (state.thread_joined == 0 or state.pending_requests != 0)
            @panic("FS controller stopped before the shared libuv service");
    }
    fn stopped(raw: *anyopaque) void {
        const self: *Controller = @ptrCast(@alignCast(raw));
        std.debug.assert(self.stopping and self.busy == 0);
        const environment = self.environment;
        const engine = self.hub.engine;
        // The earlier shared stopped() has executed each genuine Wrapper and
        // native AfterScope with JS disabled. Do not reset the actual counter.
        var handles = Scope.init(engine);
        var failure: ?anyerror = null;
        environment.requests.requireNoWaiting(environment) catch |err| {
            record(&handles, err);
            failure = err;
        };
        self.release(); // Drop only the Hub's native entitlement.
        const ignored = handles.finish(if (failure) |err|
            @as(anyerror!c.JSValue, err) else c.pi_js_undefined()) catch return;
        engine.freeValue(ignored);
    }
};

fn cancelRequest(entry: *request_state.Entry) void {
    const request: *requests.Request = @alignCast(@fieldParentPtr("entry", entry));
    if (request.native_request) |actual| {
        // An accepted cancellation still has its real eventual callback.
        _ = uv.pi_uv_fs_cancel(actual);
    }
}
fn cleanupRequest(raw: *anyopaque) void {
    const actual: *uv.PiUvFsRequest = @ptrCast(@alignCast(raw));
    uv.pi_uv_fs_request_cleanup(actual);
}
fn afterInteger(request: *requests.Request, actual: *uv.PiUvFsRequest) !void {
    const info = uv.pi_uv_fs_request_info(actual);
    if (info.kind != uv.PI_UV_FS_READ) return error.ActualFSReadCompletionRequired;
    var after: after_scope.AfterScope = undefined;
    try after.init(request, .{ .raw = actual, .run = cleanupRequest });
    return after.finish(afterIntegerBody(&after, request, info));
}
fn afterIntegerBody(after: *after_scope.AfterScope, request: *requests.Request,
    info: uv.PiUvFsInfo) !void
{
    // Read's validated Int32 length bounds every successful uv result.
    const result = std.math.cast(c_int, info.result) orelse
        return error.ActualFSReadResultRequired;
    const path: ?[]const u8 = if (info.path == null) null else
        std.mem.span(@as([*:0]const u8, @ptrCast(info.path)));
    if (try after.proceed(.{ .code = result, .syscall = "read", .path = path }))
        try request.resolve(c.JS_NewInt32(after.handles.engine.context, result));
}
fn record(s: *Scope, err: anyerror) void {
    s.boundary.escaping();
    if (err == error.OutOfMemory and !s.boundary.fatal) {
        _ = s.engine.throwNativeOutOfMemoryFatal();
        s.boundary.escaping();
    }
}

/// One native FS client on the already shared service. An ordinary loop status
/// is returned unchanged for the real bootstrap caller's native error owner.
pub fn acquire(engine: *Engine, environment: *callbacks.Environment) !Acquisition {
    try engine.checkNativeEntry();
    if ((try environment.requireEngine()) != engine)
        return error.ActualFSRequestEnvironmentMismatch;
    const hub = try env_io.get(engine);
    try hub.assertOwner();
    if (hub.stopping) return error.NativeEnvClosed;
    for (hub.resources.items) |resource|
        if (resource.tag == @as(?*const anyopaque, &controller_tag)) {
            const existing: *Controller = @ptrCast(@alignCast(resource.raw));
            if (existing.stopping or existing.environment != environment)
                return error.ActualFSRequestEnvironmentMismatch;
            return .{ .ready = existing };
        };
    const shared = switch (try shared_service.acquire(engine)) {
        .ready => |actual| actual,
        .failed => |status| return .{ .failed = status },
    };
    const self = try environment.allocator().create(Controller);
    hub.resources.ensureUnusedCapacity(engine.gpa, 1) catch |err| {
        var completion = Completion.initVoid(engine, err);
        environment.allocator().destroy(self);
        try completion.finishVoid();
        unreachable;
    };
    self.* = .{ .hub = hub, .environment = environment.retain(), .service = shared.service };
    shared.attach(.fs, .{
        .raw = self, .ready = Controller.ready,
        .complete = Controller.deliver, .abandon = Controller.abandon,
    }) catch |err| {
        var completion = Completion.initVoid(engine, err);
        environment.allocator().destroy(self);
        environment.release();
        try completion.finishVoid();
        unreachable;
    };
    // Publication has no remaining fallible/guest operation. This independent
    // native entitlement survives the earlier shared stopped() FIFO drain.
    uv.pi_uv_service_retain(shared.service);
    hub.resources.appendAssumeCapacity(.{
        .raw = self, .tag = &controller_tag,
        .stop = Controller.stop, .stopped = Controller.stopped,
    });
    return .{ .ready = self };
}

//! One native libuv service and completion FIFO per actual Env I/O Hub.
//! TCP and FS retain their own genuine actors. This owner contains only native
//! client dispatch and the shared wake/loop lifetime; no Socket or Errno input.
const std = @import("std");
const em = @import("engine.zig");
const a = @import("native_node_argument_values.zig");
const env = @import("native_env_io.zig");
const wake = @import("native_owner_wake.zig");
const completion_wake = @import("native_owner_completion.zig");
const Completion = @import("native_sdk_owned_completion.zig").Completion;
const c = em.c;
pub const uv = @cImport({ @cInclude("native_uv_tcp.h"); @cInclude("native_uv_fs.h"); });
const service_tag: u8 = 0;

pub const Kind = enum(u1) { tcp, fs };
/// Private compiled owners only. Each client stays in the Hub through this
/// resource's stopped() drain. No client pointer is sent to the native loop.
pub const Client = struct {
    raw: *anyopaque,
    ready: *const fn (*anyopaque) bool,
    complete: *const fn (*anyopaque, *uv.PiUvEvent) anyerror!void,
    abandon: *const fn (*anyopaque, *uv.PiUvEvent) anyerror!void,
};
pub const Acquisition = union(enum) { ready: *Owner, failed: c_int };
pub const Owner = struct {
    hub: *env.Hub,
    service: *uv.PiUvService,
    wake_ref: wake.Ref,
    clients: [2]?Client = .{ null, null },
    busy: bool = false,
    stopping: bool = false,

    pub fn client(self: *Owner, kind: Kind) ?Client {
        return self.clients[@intFromEnum(kind)];
    }
    pub fn attach(self: *Owner, kind: Kind, input: Client) !void {
        try self.hub.assertOwner();
        if (self.stopping or self.hub.stopping) return error.NativeEnvClosed;
        const slot = &self.clients[@intFromEnum(kind)];
        if (slot.* != null) return error.NativeUvClientAlreadyInstalled;
        slot.* = input;
    }
    fn eventClient(self: *Owner, event: *uv.PiUvEvent) !Client {
        const kind: Kind = if (uv.pi_uv_event_info(event).kind == uv.PI_UV_FS_COMPLETION) .fs else .tcp;
        return self.client(kind) orelse return error.NativeUvCompletionOwnerRequired;
    }
    fn deliver(self: *Owner, event: *uv.PiUvEvent, abandoned: bool) !void {
        if (uv.pi_uv_event_info(event).kind == uv.PI_UV_NATIVE_ALLOCATION_FAILURE)
            return error.OutOfMemory;
        const selected = try self.eventClient(event);
        if (abandoned) return selected.abandon(selected.raw, event);
        return selected.complete(selected.raw, event);
    }
    fn poll(raw: *anyopaque) !bool {
        const self: *Owner = @ptrCast(@alignCast(raw));
        try self.hub.assertOwner();
        try self.hub.engine.checkNativeEntry();
        if (self.stopping or self.hub.stopping) return error.NativeEnvClosed;
        if (self.busy or c.JS_IsJobPending(self.hub.engine.runtime)) return false;
        // Preserve the actual TCP construction/callback reentry gate before
        // consuming any shared FIFO entry. FS uses its own same-owner gate.
        for (self.clients) |optional| if (optional) |selected|
            if (!selected.ready(selected.raw)) return false;
        const event = uv.pi_uv_service_next(self.service) orelse return false;
        self.busy = true;
        defer self.busy = false;
        const engine = self.hub.engine;
        engine.native_exception_diagnostics_suppressed += 1;
        defer engine.native_exception_diagnostics_suppressed -= 1;
        var completion = Completion.initVoid(engine, self.deliver(event, false));
        uv.pi_uv_event_release(event);
        try completion.finishVoid();
        return true; // The existing Hub owns the subsequent checkpoint.
    }
    fn referenced(raw: *anyopaque) bool {
        const self: *Owner = @ptrCast(@alignCast(raw));
        return !self.stopping and uv.pi_uv_service_has_referenced(self.service) != 0;
    }
    fn stop(raw: *anyopaque) void {
        const self: *Owner = @ptrCast(@alignCast(raw));
        if (self.stopping) return;
        std.debug.assert(!self.busy);
        self.stopping = true;
        const status = uv.pi_uv_service_stop(self.service);
        const actual = uv.pi_uv_service_snapshot(self.service);
        if (status != 0 or actual.thread_joined == 0 or actual.live_handles != 0 or actual.pending_requests != 0)
            std.debug.panic("libuv service owner did not close: status={d}", .{status});
    }
    fn record(s: *a.Scope, err: anyerror) void {
        s.boundary.escaping();
        if (err == error.OutOfMemory and !s.boundary.fatal) {
            _ = s.engine.throwNativeOutOfMemoryFatal();
            s.boundary.escaping();
        }
    }
    fn stopped(raw: *anyopaque) void {
        const self: *Owner = @ptrCast(@alignCast(raw));
        const engine = self.hub.engine;
        std.debug.assert(self.stopping);
        // Hub calls every resource stop before any stopped callback. Actual FS
        // owners have disabled JS and still execute their native Wrapper/After
        // cleanup, so request_waiting reaches zero before realm destruction.
        var handles = a.Scope.init(engine);
        var failure: ?anyerror = null;
        while (uv.pi_uv_service_next(self.service)) |event| {
            self.deliver(event, true) catch |err| {
                record(&handles, err);
                if (failure == null) failure = err;
            };
            uv.pi_uv_event_release(event);
            handles.pending() catch |err| {
                record(&handles, err);
                if (failure == null) failure = err;
            };
        }
        self.clients = .{ null, null };
        uv.pi_uv_service_release(self.service);
        wake.release(self.wake_ref);
        hostDestroy(engine, self);
        const ignored = handles.finish(if (failure) |err|
            @as(anyerror!c.JSValue, err) else c.pi_js_undefined()) catch return;
        engine.freeValue(ignored);
    }
};

fn notify(slot: u32, generation: u64) callconv(.c) void {
    if (slot > std.math.maxInt(u8)) return;
    wake.notify(.{ .slot = @intCast(slot), .generation = generation });
}
fn hostCreate(engine: *em.Engine, comptime T: type) !*T {
    if (c.pi_js_native_memory_reserve(engine.native_memory_owner, @sizeOf(T)) == 0)
        return error.OutOfMemory;
    errdefer c.pi_js_native_memory_release(engine.native_memory_owner, @sizeOf(T));
    return engine.gpa.create(T);
}
fn hostDestroy(engine: *em.Engine, value: anytype) void {
    const size = @sizeOf(@TypeOf(value.*));
    engine.gpa.destroy(value);
    c.pi_js_native_memory_release(engine.native_memory_owner, size);
}

/// Domain callers preserve their own actual native-error construction for an
/// ordinary loop status. Only this wrapper's proven allocation failure is OOM.
/// Publication follows complete wake/loop/resource admission.
pub fn acquire(engine: *em.Engine) !Acquisition {
    try engine.checkNativeEntry();
    const hub = try env.get(engine);
    try hub.assertOwner();
    if (hub.stopping) return error.NativeEnvClosed;
    for (hub.resources.items) |resource| if (resource.tag == @as(?*const anyopaque, &service_tag)) {
        const self: *Owner = @ptrCast(@alignCast(resource.raw));
        if (self.stopping) return error.NativeEnvClosed;
        return .{ .ready = self };
    };
    const reference = try completion_wake.acquireNativeWake(engine);
    const self = hostCreate(engine, Owner) catch |err| {
        var completion = Completion.initVoid(engine, err);
        wake.release(reference);
        try completion.finishVoid();
        unreachable;
    };
    var service: ?*uv.PiUvService = null;
    const started = uv.pi_uv_service_create(engine.native_memory_owner, notify,
        reference.slot, reference.generation, &service);
    if (started.status < 0 or started.allocation_failed != 0) {
        var completion = Completion.initVoid(engine, if (started.allocation_failed != 0)
            @as(anyerror!void, error.OutOfMemory) else @as(anyerror!void, {}));
        hostDestroy(engine, self);
        wake.release(reference);
        try completion.finishVoid();
        return .{ .failed = started.status };
    }
    const actual = service orelse unreachable;
    hub.resources.ensureUnusedCapacity(engine.gpa, 1) catch |err| {
        var completion = Completion.initVoid(engine, err);
        if (uv.pi_uv_service_stop(actual) != 0) @panic("libuv service admission rollback did not join");
        while (uv.pi_uv_service_next(actual)) |event| uv.pi_uv_event_release(event);
        uv.pi_uv_service_release(actual);
        hostDestroy(engine, self);
        wake.release(reference);
        try completion.finishVoid();
        unreachable;
    };
    self.* = .{ .hub = hub, .service = actual, .wake_ref = reference };
    hub.resources.appendAssumeCapacity(.{
        .raw = self, .tag = &service_tag, .poll = Owner.poll,
        .referenced = Owner.referenced, .stop = Owner.stop, .stopped = Owner.stopped,
    });
    return .{ .ready = self };
}
